  summary = 'Develop advanced skill in analyzing, critiquing, and creating persuasive communication across civic, political, organizational, commercial, interpersonal, visual, and digital contexts. The course balances classical rhetoric, social influence theory, rhetorical criticism, ethics, and applied message design.',
  data = $perrjson${"slug": "persuasion-rhetoric", "title": "Persuasion / Rhetoric", "description": "Develop advanced skill in analyzing, critiquing, and creating persuasive communication across civic, political, organizational, commercial, interpersonal, visual, and digital contexts. The course balances classical rhetoric, social influence theory, rhetorical criticism, ethics, and applied message design.", "topics": [{"id": "90c8cb2c-1128-4d58-956a-6edd853f3002", "type": "topic", "title": "Rhetoric, Persuasion, and Public Life", "description": "This opening topic frames persuasion as a central practice of civic, professional, cultural, and interpersonal life. Students learn to analyze influence without reducing it to manipulation.", "children": [{"id": "b821f903-25bc-4e96-a60f-bb2e42aa5b20", "type": "subtopic", "title": "Rhetoric as situated action", "children": [{"id": "a86f2e16-3ab0-4a8b-a18f-d04b37c234d7", "type": "concept", "title": "speaker or rhetor"}, {"id": "347bb760-3d0f-4d95-bd54-d41bcd869b24", "type": "concept", "title": "audience"}, {"id": "fffcfe60-ccd8-4e23-bb0c-752b4441fefe", "type": "concept", "title": "exigence"}, {"id": "d716dd9d-32d9-4b77-8a74-8421f2e95358", "type": "concept", "title": "constraints"}], "description": "Why it matters: Rhetoric responds to concrete audiences, problems, constraints, and opportunities."}, {"id": "3ad82388-9f04-4e13-b2d3-d1ad5dba9cf6", "type": "subtopic", "title": "Persuasion versus coercion", "children": [{"id": "70881f34-b53d-487c-b900-e0d6c67b7f20", "type": "concept", "title": "choice"}, {"id": "2ea188c0-8736-46f8-b8a4-9caaff2955d3", "type": "concept", "title": "consent"}, {"id": "84f08c0d-3941-4454-8d36-f4175abaead1", "type": "concept", "title": "pressure"}, {"id": "69eca3ae-b00b-40e0-a738-30fc06b75c92", "type": "concept", "title": "agency"}], "description": "Why it matters: Students distinguish ethical influence from force, deception, and manipulation."}, {"id": "07a8fdce-82d3-47d7-a8fa-9c83673183a8", "type": "subtopic", "title": "Public life and symbolic power", "children": [{"id": "bc631cea-02d4-41fa-b6a4-43e0a2cdef7e", "type": "concept", "title": "public discourse"}, {"id": "0ec52772-3205-4fcf-8f03-5d69da828626", "type": "concept", "title": "commonplaces"}, {"id": "12d56ac7-b1be-4589-95e0-3d50b0285b53", "type": "concept", "title": "values"}, {"id": "9adbe312-d503-46b3-8a53-d437957dd0cb", "type": "concept", "title": "collective judgment"}], "description": "Why it matters: The course studies how messages define problems, values, identities, and possible action."}]}, {"id": "94e7328c-4a92-4ddc-8b5d-4d9a682916a9", "type": "topic", "title": "Classical Rhetoric: Ethos, Pathos, Logos, and Kairos", "description": "Classical rhetoric gives students a durable vocabulary for analyzing why arguments work and when they fail.", "children": [{"id": "f583bfe3-d22f-4f60-b0d8-ce28e278e6d1", "type": "subtopic", "title": "Ethos", "children": [{"id": "22849cec-3d10-4b3c-b627-6567c2dea3e1", "type": "concept", "title": "expertise"}, {"id": "7683e473-2fd7-4a3d-96b2-e2f0b3c5147c", "type": "concept", "title": "trustworthiness"}, {"id": "1015c20e-f03c-4d87-926a-ada715e48d36", "type": "concept", "title": "identification"}, {"id": "8580ee73-6ba6-476e-85f7-a5c875e5d960", "type": "concept", "title": "situated credibility"}], "description": "Why it matters: Credibility is built through character, competence, goodwill, and performance."}, {"id": "8c80d114-a1a1-4919-ad99-68568f6a852f", "type": "subtopic", "title": "Pathos", "children": [{"id": "7ee407e0-7604-424d-ab0e-48d6ec32a12b", "type": "concept", "title": "fear"}, {"id": "bf496f22-1efc-48b3-ba5c-e87dda60e8f5", "type": "concept", "title": "hope"}, {"id": "2bf753c7-8148-4aaa-849f-628fa6cf3381", "type": "concept", "title": "anger"}, {"id": "e7c6d45f-61fd-43e0-a8e9-08b3b8c479bb", "type": "concept", "title": "empathy"}], "description": "Why it matters: Emotion is not a distraction from argument; it helps audiences perceive stakes and urgency."}, {"id": "6442a7f3-2b8e-48a9-8551-dab3748d83e6", "type": "subtopic", "title": "Logos and kairos", "children": [{"id": "c4ccb6bd-0815-4ed9-b391-39c736522edf", "type": "concept", "title": "claims"}, {"id": "28100a31-4fc1-4794-89e3-3b32dfb1e7fe", "type": "concept", "title": "evidence"}, {"id": "5eb7fe09-960c-42df-989d-0d849f8a03fb", "type": "concept", "title": "timing"}, {"id": "0d51ec16-6259-4cb5-b974-15498c4a3f36", "type": "concept", "title": "occasion"}], "description": "Why it matters: Reasoning must fit the moment, evidence, and available audience assumptions."}]}, {"id": "1815106c-0023-45df-8bb8-d4a64f592b96", "type": "topic", "title": "The Rhetorical Canons and Message Craft", "description": "The five canons help students move from analysis to production: inventing ideas, arranging material, styling language, remembering structure, and delivering effectively.", "children": [{"id": "23021124-2b85-4eee-b662-4fa1fcec5266", "type": "subtopic", "title": "Invention", "children": [{"id": "6e4eea40-a4d9-47be-95aa-7d66592867ac", "type": "concept", "title": "stasis questions"}, {"id": "061d0dc3-d034-4706-b084-6cf782dccc5e", "type": "concept", "title": "common topics"}, {"id": "ca01f232-f440-4ef6-a48f-1916a479f89f", "type": "concept", "title": "audience needs"}, {"id": "3032340c-f52c-4c9b-a344-76dca558f30b", "type": "concept", "title": "evidence gathering"}], "description": "Why it matters: Students learn how to discover arguments, examples, evidence, and angles."}, {"id": "bf00126e-9f01-4d13-8a8b-9e85f1443be3", "type": "subtopic", "title": "Arrangement and style", "children": [{"id": "cdc7995f-d8ec-413c-9bb1-48e4a7fc2efe", "type": "concept", "title": "openings"}, {"id": "62799f58-902a-416c-b3aa-2f1c57731768", "type": "concept", "title": "transitions"}, {"id": "cb9af3a9-f0dc-496a-8b98-7cc2a3cf4327", "type": "concept", "title": "figures of speech"}, {"id": "189da6fa-dc84-4269-82d1-57203100c1c2", "type": "concept", "title": "clarity"}], "description": "Why it matters: Organization and language guide attention, emphasis, memory, and emotional force."}, {"id": "a1aacb46-8c2c-4f73-84a7-b32637ecca17", "type": "subtopic", "title": "Memory and delivery", "children": [{"id": "c7ef5e02-031f-4214-b846-dd54a51255bf", "type": "concept", "title": "presence"}, {"id": "2b9ac9d0-12c5-4eb8-97c3-5fef83a6e72f", "type": "concept", "title": "voice"}, {"id": "aeb0ee21-a0b6-44a9-ada1-c67dc78507c4", "type": "concept", "title": "gesture"}, {"id": "2eede741-dc06-43c5-9516-1429e66a58bf", "type": "concept", "title": "practice"}], "description": "Why it matters: Performance shapes credibility and audience connection."}]}, {"id": "ffe88f58-9f35-4d51-8412-cd7676170cf0", "type": "topic", "title": "Argumentation, Warrants, Evidence, and Fallacies", "description": "Strong persuasion depends on the quality of reasoning. This topic gives students tools to construct, test, and critique arguments.", "children": [{"id": "be234b9b-5a17-49de-889e-e7de95973597", "type": "subtopic", "title": "Argument structure", "children": [{"id": "c4483b10-53d3-446b-b6a3-b60dab7bf8c8", "type": "concept", "title": "claim"}, {"id": "c9242ece-6b92-426f-9d2e-effcbafebde1", "type": "concept", "title": "data"}, {"id": "a1af8fbc-6f74-4e47-bbb1-6748550d8d76", "type": "concept", "title": "warrant"}, {"id": "b0d5844b-ebcf-4ab4-8110-2eb5ca309279", "type": "concept", "title": "backing"}], "description": "Why it matters: Students identify how claims are supported and what assumptions connect evidence to conclusions."}, {"id": "f8898746-4dd4-42ac-8761-774d8c5a2d58", "type": "subtopic", "title": "Evidence quality", "children": [{"id": "5372d683-b426-409d-acd5-3fb4b51deff0", "type": "concept", "title": "statistics"}, {"id": "88c546ad-b8d3-46c3-af32-73dfe841d8d6", "type": "concept", "title": "examples"}, {"id": "b6175274-adf6-47a4-86fb-c636691cd922", "type": "concept", "title": "testimony"}, {"id": "520d05f5-74ce-4806-a7a9-0023a3080de7", "type": "concept", "title": "causal evidence"}], "description": "Why it matters: Persuasive evidence must be relevant, credible, sufficient, and fairly interpreted."}, {"id": "0f1ff31f-ca95-4a00-915e-6d34c604fd2d", "type": "subtopic", "title": "Fallacies and weak reasoning", "children": [{"id": "2bb941f2-70ba-499a-a3a4-210136cf11b9", "type": "concept", "title": "straw person"}, {"id": "17df43ad-a442-417c-b046-82eb33320c33", "type": "concept", "title": "false dilemma"}, {"id": "8fdd5f28-399c-4a32-b501-4469d615b747", "type": "concept", "title": "ad hominem"}, {"id": "dfc39b8a-2a42-4146-9392-3dc4aed10a11", "type": "concept", "title": "post hoc"}], "description": "Why it matters: Fallacies are not labels to throw around; they are patterns that reveal where reasoning breaks down."}]}, {"id": "104e6e04-a35d-4b17-a6d0-9931aafd55d6", "type": "topic", "title": "Audience Analysis and Rhetorical Situation", "description": "Persuasion changes when the audience changes. Students learn to adapt ethically to beliefs, identities, needs, motivations, and contexts.", "children": [{"id": "3a2b9e2a-ca19-4fca-a86d-223f8de98151", "type": "subtopic", "title": "Audience segmentation", "children": [{"id": "bc13dc77-6f52-4d34-90fb-70e75198ba64", "type": "concept", "title": "demographics"}, {"id": "d4554c29-79ca-490f-bc09-8985abd6c059", "type": "concept", "title": "psychographics"}, {"id": "99fabe71-4b25-4126-b1e7-7dacb2806cb9", "type": "concept", "title": "stakeholders"}, {"id": "5e934524-9af0-49b4-b653-baa9f60834dd", "type": "concept", "title": "prior knowledge"}], "description": "Why it matters: Students learn to identify meaningful audience differences without stereotyping."}, {"id": "2d709f7f-b0c5-4c42-aeb8-9a782edd0fac", "type": "subtopic", "title": "Constraints and affordances", "children": [{"id": "bd195aeb-6bd4-4ffa-9fda-c37fd678fad4", "type": "concept", "title": "genre"}, {"id": "c7cd864a-a888-40ee-93f8-f7ec6eb02a06", "type": "concept", "title": "platform"}, {"id": "55d14d5f-8547-4d33-86d8-993c90e2e25c", "type": "concept", "title": "institution"}, {"id": "35b5b4d9-3e49-424b-932e-c3fa95635348", "type": "concept", "title": "urgency"}], "description": "Why it matters: Every persuasive situation contains limits and possibilities shaped by setting, medium, norms, and timing."}, {"id": "098d0981-8c0e-46e9-9d89-8cd27a64bd78", "type": "subtopic", "title": "Audience adaptation", "children": [{"id": "769c9544-da23-4028-9384-aa48811c1f37", "type": "concept", "title": "framing"}, {"id": "d1cb232b-536e-44f9-9e38-45f155842bdc", "type": "concept", "title": "language choice"}, {"id": "b230d0a5-9478-4eb4-be28-cdfedb250c01", "type": "concept", "title": "examples"}, {"id": "3bfe18f7-0c03-4102-bea1-159bd43d916a", "type": "concept", "title": "call to action"}], "description": "Why it matters: Effective messages connect with audience values while maintaining truthfulness and integrity."}]}, {"id": "9cd4c2bc-cee3-42c5-a19d-e7f7fe36d6ee", "type": "topic", "title": "Attitudes, Beliefs, and Attitude Change", "description": "This topic links persuasion to social psychology. Students learn how attitudes form, why they persist, and what makes change possible.", "children": [{"id": "d3b9cf6d-f496-4932-90ee-990a70d6b319", "type": "subtopic", "title": "Attitude components", "children": [{"id": "d256736e-6ab1-4b34-b75a-d1b08df60fb2", "type": "concept", "title": "cognition"}, {"id": "0e687ebf-aa0c-4eb4-ad2e-0f596270aefc", "type": "concept", "title": "affect"}, {"id": "3ccb8581-de48-4fc8-895c-c64c594935cc", "type": "concept", "title": "behavior"}, {"id": "36ed5836-7e94-4b11-9e41-84e474c310bf", "type": "concept", "title": "ambivalence"}], "description": "Why it matters: Attitudes include beliefs, feelings, and behavioral tendencies."}, {"id": "eba15597-c27f-49db-9c24-af6abeac0b94", "type": "subtopic", "title": "Attitude strength", "children": [{"id": "665f66e9-92ea-4bfd-86ae-16a35a733365", "type": "concept", "title": "certainty"}, {"id": "d3e16cb8-bf16-42d4-b774-d527f64fef52", "type": "concept", "title": "importance"}, {"id": "2fb374f9-485e-4322-87df-51d07d8b4a00", "type": "concept", "title": "accessibility"}, {"id": "33912179-c4a6-4d03-95c0-2067b1660f3a", "type": "concept", "title": "knowledge"}], "description": "Why it matters: Strong attitudes are more durable, accessible, and predictive of action."}, {"id": "cfab1308-a9b7-4e38-b8ff-156478909f4b", "type": "subtopic", "title": "Behavior change", "children": [{"id": "1f1932fa-8443-432b-95e2-eda4bbc2fc3a", "type": "concept", "title": "intentions"}, {"id": "32b46d83-3164-4d36-8148-2da77f27f05a", "type": "concept", "title": "social norms"}, {"id": "35dd581e-d80f-4bc8-881d-a33e9bf28fcc", "type": "concept", "title": "self-efficacy"}, {"id": "2afb51b9-2b79-4d92-9e23-28f4d8df1d0b", "type": "concept", "title": "barriers"}], "description": "Why it matters: Students examine why attitude change does not always translate into action."}]}, {"id": "598503f0-38d8-4cc1-9dd9-92988e310d68", "type": "topic", "title": "Cognitive Dissonance, Consistency, and Resistance", "description": "People often defend existing beliefs even when confronted with contrary evidence. Students learn how consistency motives shape persuasion and resistance.", "children": [{"id": "9e4c483b-47e2-475f-8002-115852c9b7cb", "type": "subtopic", "title": "Dissonance theory", "children": [{"id": "bf97f58e-cfea-40b9-bf22-e565bf01e232", "type": "concept", "title": "inconsistency"}, {"id": "38c2ce3a-acf2-4618-9124-daf5ea195464", "type": "concept", "title": "justification"}, {"id": "1e28a920-afa7-4cb0-8d86-ac336650adf8", "type": "concept", "title": "selective exposure"}, {"id": "6af3a5c0-3d53-461b-85ee-7535fe10b3e5", "type": "concept", "title": "post-decision dissonance"}], "description": "Why it matters: Dissonance explains discomfort when beliefs, actions, or identities conflict."}, {"id": "60b8363c-ed17-4768-a775-d6ee5a055c5f", "type": "subtopic", "title": "Resistance to persuasion", "children": [{"id": "64b95391-bd1a-45a8-b753-83e67c873d8b", "type": "concept", "title": "reactance"}, {"id": "07c3dc3c-c837-4db5-b2d6-8daff9c95562", "type": "concept", "title": "inoculation"}, {"id": "4a1cb325-277f-4a27-b088-0b501acbcbca", "type": "concept", "title": "motivated reasoning"}, {"id": "65cbf0f3-f0cb-44e2-81c0-3d25f26e2e89", "type": "concept", "title": "identity protection"}], "description": "Why it matters: Audiences may counterargue, avoid, reinterpret, or reject persuasive messages."}, {"id": "e484a95e-f464-4e69-9d7f-b34bd8406412", "type": "subtopic", "title": "Ethical change strategies", "children": [{"id": "96ddfda2-40ec-4528-964b-dd957b6d2cef", "type": "concept", "title": "affirmation"}, {"id": "50d07424-6056-4526-9e9b-d34b2077a9b2", "type": "concept", "title": "small commitments"}, {"id": "e267b2b2-f3da-4911-9097-4cb4422bc43b", "type": "concept", "title": "dialogue"}, {"id": "9be185b7-dc26-4eaa-a74b-29b3b41b46bb", "type": "concept", "title": "self-persuasion"}], "description": "Why it matters: Students practice reducing defensiveness while respecting agency."}]}, {"id": "1b18e5f9-9347-4be3-904d-98ab04d63200", "type": "topic", "title": "Elaboration Likelihood and Dual-Process Models", "description": "Dual-process models help explain when audiences think deeply and when they rely on cues. Students learn to design and critique messages for different processing conditions.", "children": [{"id": "35fc10f0-379c-46a3-a47d-9218d43b0ddf", "type": "subtopic", "title": "Central processing", "children": [{"id": "79fcc092-2ae5-4e38-9229-6598c5fc84e3", "type": "concept", "title": "issue relevance"}, {"id": "9ba3a6bc-d035-4335-8b7c-4d49db69de2a", "type": "concept", "title": "evidence"}, {"id": "de6cd2fb-e7fb-45fe-9e57-fe1c90866007", "type": "concept", "title": "reasoning"}, {"id": "253e73b9-0dec-4118-bbd1-571081961fd4", "type": "concept", "title": "counterargument"}], "description": "Why it matters: When motivation and ability are high, audiences scrutinize argument quality."}, {"id": "299174f2-8bee-408c-ad5d-9e33a76ffa43", "type": "subtopic", "title": "Peripheral processing", "children": [{"id": "4d05b2d9-0f50-4174-889d-e3981de696a3", "type": "concept", "title": "source cues"}, {"id": "2f4a586e-e5df-40d6-9f2e-7e9c4b32a587", "type": "concept", "title": "social proof"}, {"id": "f48ee6ff-8e4b-4d79-b733-770586747c66", "type": "concept", "title": "liking"}, {"id": "b07e58e1-8df6-4e96-9212-0f92e4a11a0b", "type": "concept", "title": "scarcity"}], "description": "Why it matters: When attention or ability is low, audiences rely more on cues and heuristics."}, {"id": "37b22390-4c3a-4668-b47b-fa47b5835649", "type": "subtopic", "title": "Message design implications", "children": [{"id": "bb023bf2-d65d-4d64-8682-82c37b5c236a", "type": "concept", "title": "motivation"}, {"id": "91e088da-4aba-4f41-b77b-3946a995b8c8", "type": "concept", "title": "ability"}, {"id": "999c07c9-e002-474c-9713-a4eac8f64084", "type": "concept", "title": "cognitive load"}, {"id": "07570ee9-d1c1-416f-bd62-1bf6e9afd240", "type": "concept", "title": "durability of change"}], "description": "Why it matters: Students match persuasive strategy to audience involvement and ethical responsibility."}]}, {"id": "9d0955f5-af62-4bbf-a99a-89b6e41f9841", "type": "topic", "title": "Narrative, Metaphor, and Framing", "description": "Stories and frames organize how people interpret reality. This topic teaches students to analyze the symbolic structures that make some conclusions feel natural.", "children": [{"id": "c62e72f8-9e5b-4266-8dba-a3abf403524f", "type": "subtopic", "title": "Narrative persuasion", "children": [{"id": "0af000ee-da1c-4b91-a807-202236ab0600", "type": "concept", "title": "transportation"}, {"id": "481f1545-d4b0-4e9c-89fd-2fad0343135f", "type": "concept", "title": "characters"}, {"id": "fad8dcb1-729c-47d6-a693-84eeae3e70ea", "type": "concept", "title": "plot"}, {"id": "f8913657-13b3-45e9-a653-3822d07b4b6e", "type": "concept", "title": "moral"}], "description": "Why it matters: Stories can reduce resistance, build identification, and make abstract issues concrete."}, {"id": "06f68caf-8df3-4672-a6f3-c8be5ebeec01", "type": "subtopic", "title": "Metaphor and analogy", "children": [{"id": "3c288bb3-a4f4-4cdd-ba9f-8fdd1fc1aa67", "type": "concept", "title": "source domain"}, {"id": "dd219cc7-de3e-4805-b1a6-597cb031f495", "type": "concept", "title": "target domain"}, {"id": "3912b0b9-d0a7-4dc7-9115-d228b7ee0f03", "type": "concept", "title": "conceptual metaphor"}, {"id": "94fd0c34-0f6b-47bb-ab60-a80ab492bc5c", "type": "concept", "title": "limits of analogy"}], "description": "Why it matters: Metaphors invite audiences to reason about one domain through another."}, {"id": "e19f7225-13a2-47c0-b1a4-ffb46f8b26b0", "type": "subtopic", "title": "Framing", "children": [{"id": "af78e963-387b-4de3-b14b-6469d5e0be5f", "type": "concept", "title": "problem definition"}, {"id": "4fdba336-ca8c-4e20-bcc4-d9d765186990", "type": "concept", "title": "causal interpretation"}, {"id": "fd524861-6779-4a02-834a-b95953fa95d8", "type": "concept", "title": "moral evaluation"}, {"id": "6405c7c8-acf9-4304-99c7-06ce104d2da9", "type": "concept", "title": "remedy"}], "description": "Why it matters: Frames select some aspects of reality and make them more salient."}]}, {"id": "57342e2d-034d-4901-93e9-4e5d3fe30e0e", "type": "topic", "title": "Propaganda, Manipulation, and Misinformation", "description": "A world-class persuasion course must teach students to recognize influence used to distort judgment and public knowledge.", "children": [{"id": "487a5cfa-081a-4c0e-a270-1224d378cd23", "type": "subtopic", "title": "Propaganda techniques", "children": [{"id": "0772c612-c097-4939-800c-c04370943767", "type": "concept", "title": "name-calling"}, {"id": "01044dcb-c2a3-4612-8e4d-e292a5e577b4", "type": "concept", "title": "glittering generalities"}, {"id": "58f9dc74-aaf1-4a51-aa2b-6effdb60cbf0", "type": "concept", "title": "bandwagon"}, {"id": "c6529f0d-20e4-4008-915b-8d4e2621c4f4", "type": "concept", "title": "scapegoating"}], "description": "Why it matters: Students identify recurring strategies us